import{_ as p,a0 as o,w as l,s as r,ao as g,I as n,x as s,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"科學音頻處理（三）：如何使用 Octave 的高級數學技術處理音頻文件 | LCTT x X-CMD","titleTemplate":false,"description":"科學音頻處理（三）：如何使用 Octave 的高級數學技術處理音頻文件 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"科學音頻處理（三）：如何使用 Octave 的高級數學技術處理音頻文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"科學音頻處理（三）：如何使用 Octave 的高級數學技術處理音頻文件 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160622 Part III - How to apply Advanced Mathematical Processing Effects on Audio files with Octave 4.0 on Ubuntu","title":"科學音頻處理（三）：如何使用 Octave 的高級數學技術處理音頻文件","tag":"201610","desc":""},"relativePath":"201610/20160622 Part III - How to apply Advanced Mathematical Processing Effects on Audio files with Octave 4.0 on Ubuntu.md","filePath":"[post].md"}'),d={name:"201610/20160622 Part III - How to apply Advanced Mathematical Processing Effects on Audio files with Octave 4.0 on Ubuntu.md"};function c(h,a,u,f,m,b){const t=o("Link");return l(),r("div",null,[a[13]||(a[13]=g(`<h1 id="科學音頻處理-三-如何使用-octave-的高級數學技術處理音頻文件" tabindex="-1">科學音頻處理（三）：如何使用 Octave 的高級數學技術處理音頻文件 <a class="header-anchor" href="#科學音頻處理-三-如何使用-octave-的高級數學技術處理音頻文件" aria-label="Permalink to “科學音頻處理（三）：如何使用 Octave 的高級數學技術處理音頻文件”">​</a></h1><p>我們的數字音頻處理技術第三部分涵蓋了信號調製內容，將解釋如何進行調幅（Amplitude Modulation）、顫音效果（Tremolo Effect）和頻率變化（Frequency Variation）。</p><h3 id="調製" tabindex="-1">調製 <a class="header-anchor" href="#調製" aria-label="Permalink to “調製”">​</a></h3><h4 id="調幅" tabindex="-1">調幅 <a class="header-anchor" href="#調幅" aria-label="Permalink to “調幅”">​</a></h4><p>正如它的名字暗示的那樣， 影響正弦信號的振幅變化依據傳遞的信息而不斷改變。正弦波因為承載着大量的信息被稱作載波（carrier）。這種調製技術被用於許多的商業廣播和市民信息傳輸波段（AM）。</p><h4 id="為何要使用調幅技術" tabindex="-1">為何要使用調幅技術？ <a class="header-anchor" href="#為何要使用調幅技術" aria-label="Permalink to “為何要使用調幅技術？”">​</a></h4><p><strong>調製發射</strong></p><p>假設信道是免費資源，有天線就可以發射和接收信號。這要求有效的電磁信號發射天線，它的大小和要被髮射的信號的波長應該是同一數量級。很多信號，包括音頻成分，通常在 100 赫茲或更低。對於這些信號，如果直接發射，我們就需要建立長達 300 公里的天線。如果通過信號調製將信息加載到 100MHz 的高頻載波中，那麼天線僅僅需要 1 米（橫向長度）。</p><p><strong>集中調製與多通道</strong></p><p>假設多個信號佔用一個通道，調製可以將不同的信號不同頻域位置，以便接收者選擇該特定信號。使用集中調製（“複用”）的應用有遙感探測數據、立體聲調頻收音機和長途電話等。</p><p><strong>克服設備限制的調製</strong></p><p>信號處理設備，比如過濾器、放大器，以及可以用它們簡單組成的設備，它們的性能依賴於信號在頻域中的境況以及高頻率和低頻信號的關係。調製可以用於傳遞信號到頻域中的更容易滿足設計需求的位置。調製也可以將“寬帶信號“（高頻和低頻的比例很大的信號）轉換成”窄帶“信號。</p><p><strong>音頻特效</strong></p><p>許多音頻特效由於引人注目和處理信號的便捷性使用了調幅技術。我們可以説出很多，比如顫音、合唱、鑲邊等等。這種實用性就是我們關注它的原因。</p><h3 id="顫音效果" tabindex="-1">顫音效果 <a class="header-anchor" href="#顫音效果" aria-label="Permalink to “顫音效果”">​</a></h3><p>顫音效果是調幅最簡單的應用，為實現這樣的效果，我們會用週期信號改變（乘）音頻信號，使用正弦或其他。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; tremolo=&#39;tremolo.ogg&#39;;</span></span>
<span class="line"><span>&gt;&gt; fs=44100;</span></span>
<span class="line"><span>&gt;&gt; t=0:1/fs:10;</span></span>
<span class="line"><span>&gt;&gt; wo=2*pi*440*t;</span></span>
<span class="line"><span>&gt;&gt; wa=2*pi*1.2*t;</span></span>
<span class="line"><span>&gt;&gt; audiowrite(tremolo, cos(wa).*cos(wo),fs);</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/tremolo.png" alt="Tremolo"></p><p>這將創造一個正弦形狀的信號，它的效果就像‘顫音’。</p><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/tremoloshape.png" alt="Tremolo Shape"></p><h3 id="在真實音頻文件中的顫音" tabindex="-1">在真實音頻文件中的顫音 <a class="header-anchor" href="#在真實音頻文件中的顫音" aria-label="Permalink to “在真實音頻文件中的顫音”">​</a></h3><p>現在我們將展示真實世界中的顫音效果。首先，我們使用之前記錄過男性發聲 ‘A’ 的音頻文件。這個信號圖就像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [y,fs]=audioread(&#39;A.ogg&#39;);</span></span>
<span class="line"><span>&gt;&gt; plot(y);</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/avocalmale.png" alt="Vocal"></p><p>現在我們將創建一個完整的正弦信號，使用如下的參數：</p><ul><li>增幅 = 1</li><li>頻率= 1.5Hz</li><li>相位 = 0</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; t=0:1/fs:4.99999999;</span></span>
<span class="line"><span>&gt;&gt; t=t(:);</span></span>
<span class="line"><span>&gt;&gt; w=2*pi*1.5*t;</span></span>
<span class="line"><span>&gt;&gt; q=cos(w);</span></span>
<span class="line"><span>&gt;&gt; plot(q);</span></span></code></pre></div><p>注意： 當我們創建一組時間值時，默認情況下，它是以列的格式呈現，如, 1x220500 的值。為了乘以這樣的值，必須將其變成行的形式（220500x1）。這就是 <code>t=t(:)</code> 命令的作用。</p><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/sinusoidal.png" alt="Sinusodial"></p><p>我們將創建第二份 ogg 音頻格式的文件，它包含了如下的調製信號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; tremolo=&#39;tremolo.ogg&#39;;</span></span>
<span class="line"><span>&gt;&gt; audiowrite(tremolo, q.*y,fs);</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/tremsignal1.png" alt=""></p><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/tremolsignal1.png" alt="Tremolo Signal"></p><h3 id="頻率變化" tabindex="-1">頻率變化 <a class="header-anchor" href="#頻率變化" aria-label="Permalink to “頻率變化”">​</a></h3><p>我們可以改變頻率實現一些有趣的音效，比如原音變形，電影音效，多人比賽。</p><h4 id="正弦頻率調製的影響" tabindex="-1">正弦頻率調製的影響 <a class="header-anchor" href="#正弦頻率調製的影響" aria-label="Permalink to “正弦頻率調製的影響”">​</a></h4><p>這是正弦調製頻率變化的演示代碼，根據方程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Y=Ac*Cos(wo*Cos(wo/k))</span></span></code></pre></div><p>這裏：</p><ul><li>Ac = 增幅</li><li>wo = 基頻</li><li>k = 標量除數</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; fm=&#39;fm.ogg&#39;;</span></span>
<span class="line"><span>&gt;&gt; fs=44100;</span></span>
<span class="line"><span>&gt;&gt; t=0:1/fs:10;</span></span>
<span class="line"><span>&gt;&gt; w=2*pi*442*t;</span></span>
<span class="line"><span>&gt;&gt; audiowrite(fm, cos(cos(w/1500).*w), fs);</span></span>
<span class="line"><span>&gt;&gt; [y,fs]=audioread(&#39;fm.ogg&#39;);</span></span>
<span class="line"><span>&gt;&gt; figure (); plot (y);</span></span></code></pre></div><p>信號圖：</p><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/fmod.png" alt=""></p><p>你可以使用幾乎任何類型的週期函數頻率調製。本例中，我們僅僅用了一個正弦函數。請大膽的改變函數頻率，用複合函數，甚至改變函數的類型。</p><hr>`,45)),n("p",null,[a[1]||(a[1]=s("via: ",-1)),e(t,{href:"https://www.howtoforge.com/tutorial/ubuntu-octave-audio-processing-part-3/"},{default:i(()=>[...a[0]||(a[0]=[s("https://www.howtoforge.com/tutorial/ubuntu-octave-audio-processing-part-3/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=s("作者：",-1)),e(t,{href:"https://www.howtoforge.com/tutorial/ubuntu-octave-audio-processing-part-3/"},{default:i(()=>[...a[2]||(a[2]=[s("David Duarte",-1)])]),_:1}),a[6]||(a[6]=s(" 譯者：",-1)),e(t,{href:"https://github.com/theArcticOcean"},{default:i(()=>[...a[3]||(a[3]=[s("theArcticOcean",-1)])]),_:1}),a[7]||(a[7]=s(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[s("Linux中國",-1)])]),_:1}),a[12]||(a[12]=s(" 榮譽推出",-1))])])}const y=p(d,[["render",c]]);export{v as __pageData,y as default};
